import os
import pandas as pd
import numpy as np

def task_func(data_dir: str, csv_file: str) -> pd.DataFrame:
    # Check if the file exists
    if not os.path.exists(os.path.join(data_dir, csv_file)):
        raise FileNotFoundError(f"The file {csv_file} does not exist in the directory {data_dir}.")

    # Read the CSV file into a DataFrame
    df = pd.read_csv(os.path.join(data_dir, csv_file))

    # Check if the DataFrame is empty
    if df.empty:
        return pd.DataFrame()

    # Fill NaN values in numeric columns with the mean of the corresponding column
    for column in df.select_dtypes(include=np.number).columns:
        df[column].fillna(df[column].mean(), inplace=True)

    return df
